mapper.select:
SELECT COUNT(*)
FROM member_saved_link
WHERE created_by_member_id = #{memberId}
AND member_folder_id = #{folderId}
AND link_id = #{linkId}
AND deleted_at IS NULL

SELECT msl.*, l.original_url, l.canonical_url, l.domain, l.thumbnail_url
FROM member_saved_link msl
JOIN link l ON msl.link_id = l.link_id
WHERE msl.created_by_member_id = #{memberId}
AND msl.member_saved_link_id = #{bookmarkId}
AND msl.deleted_at IS NULL

SELECT * FROM link
WHERE canonical_url = #{canonicalUrl}
AND deleted_at IS NULL

mapper.update:
UPDATE member_saved_link
SET deleted_at = now(),
    deleted_by_member_id = #{memberId}
WHERE member_saved_link_id = #{bookmarkId}
AND created_by_member_id = #{memberId}
AND deleted_at IS NULL
